    // Dedicated Showcase 4: Activity Dashboard
    'activity.badge': 'ਵੈੱਬ ਗਤੀਵਿਧੀ',
    'activity.title': 'ਵੈੱਬ ਗਤੀਵਿਧੀ: ਤੁਹਾਡਾ ਦਿਨ ਕਿੱਥੇ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਤੁਸੀਂ ਇਸ ਬਾਰੇ ਕੀ ਕਰਦੇ ਹੋ',
    'activity.subtitle':
        'ਸਾਈਡ ਪੈਨਲ ਵਿੱਚ ਅੱਜ ਦਾ ਹਿਸਾਬ ਹੈ; ਪੂਰੇ ਪੰਨੇ ਵਿੱਚ ਬਾਕੀ ਸਭ। ਹਰ ਸਾਈਟ ਅਤੇ ਹਰ ਸ਼੍ਰੇਣੀ ਅਨੁਸਾਰ ਸਮਾਂ, ਅਤੇ ਨਿਯਮ ਜੋ ਕਿਸੇ ਸਾਈਟ ਨੂੰ ਰੋਕ ਦਿੰਦੇ ਹਨ ਜਦੋਂ ਉਹ ਤੁਹਾਡੇ ਦਿਨ ਦਾ ਕਾਫ਼ੀ ਹਿੱਸਾ ਲੈ ਚੁੱਕੀ ਹੋਵੇ। ਸਭ ਕੁਝ ਇਸੇ ਡਿਵਾਈਸ ’ਤੇ ਦਰਜ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਕੁਝ ਵੀ ਕਿਤੇ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।',
    'activity.f1.title': 'ਅੱਜ, ਉਸ ਪੰਨੇ ਦੇ ਨਾਲ ਜਿਸ ’ਤੇ ਤੁਸੀਂ ਹੋ',
    'activity.f1.desc':
        'ਹਰ ਸਾਈਟ ਲਈ ਇੱਕ ਸਮੇਟਿਆ ਬਾਕਸ, ਉਸ ’ਤੇ ਲੱਗੇ ਸਮੇਂ ਨਾਲ। ਇਸਨੂੰ ਖੋਲ੍ਹੋ ਅਤੇ ਤੁਹਾਨੂੰ ਵਿਜ਼ਿਟਾਂ, ਪ੍ਰਤੀ ਵਿਜ਼ਿਟ ਔਸਤ ਸਮਾਂ, ਦਿਨ ਵਿੱਚ ਉਸਦਾ ਹਿੱਸਾ, ਅਤੇ ਉਸ ’ਤੇ ਲਾਗੂ ਤਿੰਨ ਨਿਯਮ ਮਿਲਦੇ ਹਨ।',
    'activity.f2.title': 'ਰੋਜ਼ਾਨਾ ਸੀਮਾ, ਹਫ਼ਤਾਵਾਰੀ ਸੀਮਾ, ਅਤੇ ਖੁੱਲ੍ਹਣ ਦੇ ਘੰਟੇ',
    'activity.f2.desc':
        'ਜਦੋਂ ਕੋਈ ਖਤਮ ਹੁੰਦੀ ਹੈ ਤਾਂ ਸਾਈਟ ਸੱਚਮੁੱਚ ਬਲੌਕ ਹੋ ਜਾਂਦੀ ਹੈ, ਇੱਕ ਸਕ੍ਰੀਨ ’ਤੇ ਜੋ ਦੱਸਦੀ ਹੈ ਕਿ ਕਿਉਂ ਅਤੇ ਕਦੋਂ ਖੁੱਲ੍ਹੇਗੀ। ਨਿਯਮ ਬੰਦ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਪਾਸਵਰਡ ਮੰਗਿਆ ਜਾ ਸਕਦਾ ਹੈ, ਅਤੇ "ਪੰਜ ਮਿੰਟ ਹੋਰ" ਸਨੂਜ਼ ਵਜੋਂ ਦਰਜ ਹੁੰਦਾ ਹੈ।',
    'activity.f3.title': 'ਪੂਰਾ ਰਿਕਾਰਡ, ਇੱਕ ਪੂਰੇ ਪੰਨੇ ਵਿੱਚ',
    'activity.f3.desc':
        'ਬ੍ਰਾਊਜ਼ਿੰਗ ਦਾ ਸਮਾਂ, ਧਿਆਨ ਅਨੁਪਾਤ, ਸਿਖਰਲਾ ਘੰਟਾ, ਸਭ ਤੋਂ ਰੁਝੇਵੇਂ ਵਾਲਾ ਹਫ਼ਤੇ ਦਾ ਦਿਨ, ਲਗਾਤਾਰ ਸਮੇਂ, ਲੜੀ ਅਤੇ ਮੁੱਖ ਸ਼੍ਰੇਣੀ, ਘੰਟਾ-ਦਰ-ਘੰਟਾ ਗਰਿੱਡ, ਸ਼੍ਰੇਣੀ-ਵਾਰ ਵੰਡ, ਅਤੇ ਸਮਾਂ-ਰੇਖਾ ’ਤੇ ਹਰ ਵਿਜ਼ਿਟ ਸਮੇਤ।',
