    'bookmarks.f2.title': 'ਇਹ ਉਹ ਬੁੱਕਮਾਰਕ ਲੱਭਦਾ ਹੈ ਜੋ ਹੁਣ ਕੰਮ ਨਹੀਂ ਕਰਦੇ',
    'bookmarks.f2.desc':
        'ਇੱਕ ਸਕੈਨ ਹਰ ਸੰਭਾਲੇ ਪਤੇ ’ਤੇ ਜਾਂਦਾ ਹੈ ਅਤੇ ਅਸਫਲ ਹੋਣ ਵਾਲਿਆਂ ਦੀ ਰਿਪੋਰਟ ਦਿੰਦਾ ਹੈ, ਗਲਤੀ ਅਨੁਸਾਰ ਛਾਂਟ ਕੇ: 4xx, 5xx, ਸਮਾਂ ਸਮਾਪਤ ਜਾਂ ਕਨੈਕਸ਼ਨ ਗਲਤੀ। ਇੱਕ ਕਿਸਮ ਫਿਲਟਰ ਕਰੋ ਅਤੇ ਉਹਨਾਂ ਨੂੰ ਇਕੱਠੇ ਮਿਟਾਓ।',
