    'trust.tell': 'Pomodoro ਅਤੇ ਸਮਾਂ-ਸੀਮਾ ਸੂਚਨਾਵਾਂ, ਅਤੇ URL, ਸਕ੍ਰੀਨਸ਼ੌਟ ਜਾਂ ਰੰਗ ਨੂੰ ਕਲਿੱਪਬੋਰਡ ’ਤੇ ਕਾਪੀ ਕਰਨਾ।',
