    // Privacy Policy: the standalone /privacy page
    'privacy.meta.title': 'ਪਰਦੇਦਾਰੀ ਨੀਤੀ | Intelligent Workspace',
    'privacy.meta.description':
        'Intelligent Workspace ਕੀ ਸਟੋਰ ਕਰਦਾ ਹੈ, ਕਿੱਥੇ ਸਟੋਰ ਕਰਦਾ ਹੈ, ਅਤੇ ਉਹ ਕੁਝ ਪਲ ਜਦੋਂ ਕੁਝ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਤੋਂ ਬਾਹਰ ਜਾਂਦਾ ਹੈ। ਕੋਈ ਖਾਤਾ ਨਹੀਂ, ਸਾਡਾ ਕੋਈ ਸਰਵਰ ਨਹੀਂ, ਕੋਈ ਵਿਸ਼ਲੇਸ਼ਣ ਨਹੀਂ।',
    'privacy.eyebrow': 'ਕਾਨੂੰਨੀ',
    'privacy.title': 'ਪਰਦੇਦਾਰੀ ਨੀਤੀ',
    'privacy.effective': 'ਲਾਗੂ ਹੋਣ ਦੀ ਮਿਤੀ:',
    'privacy.lede':
        'ਕੋਈ ਖਾਤਾ ਬਣਾਉਣ ਦੀ ਲੋੜ ਨਹੀਂ, ਸਾਡਾ ਕੋਈ ਸਰਵਰ ਨਹੀਂ ਜਿਸ ਨਾਲ ਗੱਲ ਹੋਵੇ, ਅਤੇ ਐਕਸਟੈਂਸ਼ਨ ਵਿੱਚ ਕੁਝ ਵੀ ਅਜਿਹਾ ਨਹੀਂ ਜੋ ਜਾਣਕਾਰੀ ਵਾਪਸ ਭੇਜੇ। ਇਸ ਲਈ ਇਸ ਦਸਤਾਵੇਜ਼ ਵਿੱਚ ਵਾਅਦੇ ਘੱਟ ਅਤੇ ਵੇਰਵੇ ਵੱਧ ਹਨ: ਕੀ ਸਟੋਰ ਹੁੰਦਾ ਹੈ, ਕਿੱਥੇ ਰਹਿੰਦਾ ਹੈ, ਅਤੇ ਹਰ ਉਹ ਪਲ ਜਦੋਂ ਕੁਝ ਨੈੱਟਵਰਕ ਪਾਰ ਕਰਦਾ ਹੈ।',
    'privacy.toc': 'ਇਸ ਪੰਨੇ ’ਤੇ',

    'privacy.sum1.title': 'ਕੋਈ ਖਾਤਾ ਨਹੀਂ, ਕੋਈ ਸਰਵਰ ਨਹੀਂ',
    'privacy.sum1.desc':
        'ਐਕਸਟੈਂਸ਼ਨ ਵਿੱਚ ਤੁਸੀਂ ਜੋ ਵੀ ਕਰਦੇ ਹੋ ਉਹ ਸਾਨੂੰ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ। ਦੂਜੇ ਪਾਸੇ ਕੋਈ “ਅਸੀਂ” ਹੈ ਹੀ ਨਹੀਂ: ਨਾ ਬੈਕਐਂਡ, ਨਾ ਡਾਟਾਬੇਸ, ਨਾ ਤੁਹਾਡੇ ਨਾਮ ਵਾਲਾ ਕੋਈ ਲੌਗ।',
    'privacy.sum2.title': 'ਤੁਹਾਡੀ ਕੁੰਜੀ, ਤੁਹਾਡਾ ਟ੍ਰੈਫਿਕ',
    'privacy.sum2.desc':
        'ਸਹਾਇਕ ਤੁਹਾਡੀ ਪੇਸਟ ਕੀਤੀ ਕੁੰਜੀ ਨਾਲ, ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਤੋਂ, ਤੁਹਾਡੇ ਕੋਟੇ ਅਧੀਨ Google ਨਾਲ ਗੱਲ ਕਰਦਾ ਹੈ। ਵਿਚਕਾਰ ਸਾਡਾ ਕੋਈ ਪ੍ਰੌਕਸੀ ਨਹੀਂ ਜੋ ਇਸਨੂੰ ਪੜ੍ਹੇ।',
