    'privacy.sum3.desc':
        'ਨਾ ਇਸ਼ਤਿਹਾਰ, ਨਾ ਡਾਟਾ ਦਲਾਲ, ਨਾ ਟੈਲੀਮੈਟਰੀ ਐਂਡਪੁਆਇੰਟ, ਅਤੇ ਤੁਹਾਡਾ ਕੋਈ ਪ੍ਰੋਫਾਈਲ ਨਹੀਂ ਜੋ ਕੋਈ ਖਰੀਦ ਸਕੇ।',

