    'privacy.basic.heading': 'ਡਾਟਾ ਸੁਰੱਖਿਆ ਬਾਰੇ ਮੁੱਢਲੀ ਜਾਣਕਾਰੀ',
    'privacy.basic.controller': 'ਕੰਟਰੋਲਰ',
    'privacy.basic.controllerV': 'Luis Reoyo (GENKI Organización), ਸਪੇਨ।',
    'privacy.basic.purpose': 'ਮਕਸਦ',
    'privacy.basic.purposeV':
        'ਤੁਹਾਡੀ ਆਪਣੀ ਡਿਵਾਈਸ ’ਤੇ ਐਕਸਟੈਂਸ਼ਨ ਦੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਚਲਾਉਣਾ, ਅਤੇ ਇਹ ਵੈੱਬਸਾਈਟ ਪ੍ਰਦਾਨ ਕਰਨਾ।',
    'privacy.basic.basis': 'ਕਾਨੂੰਨੀ ਆਧਾਰ',
    'privacy.basic.basisV':
        'ਤੁਹਾਡੀ ਸਹਿਮਤੀ, ਜੋ ਐਕਸਟੈਂਸ਼ਨ ਇੰਸਟੌਲ ਕਰਕੇ ਅਤੇ ਹਰ ਵਿਕਲਪਿਕ ਵਿਸ਼ੇਸ਼ਤਾ ਚਾਲੂ ਕਰਕੇ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ, ਅਤੇ ਵੈੱਬਸਾਈਟ ਪ੍ਰਦਾਨ ਕਰਨ ਤੇ ਸੁਰੱਖਿਅਤ ਰੱਖਣ ਵਿੱਚ ਸਾਡਾ ਜਾਇਜ਼ ਹਿੱਤ।',
    'privacy.basic.recipients': 'ਪ੍ਰਾਪਤਕਰਤਾ',
    'privacy.basic.recipientsV':
        'ਡਿਫਾਲਟ ਤੌਰ ’ਤੇ ਕੋਈ ਨਹੀਂ। ਤੁਹਾਡੇ ਵੱਲੋਂ ਖੁਦ ਚਲਾਈ ਗਈ ਕੋਈ ਵਿਸ਼ੇਸ਼ਤਾ Google, ਰੇਡੀਓ ਡਾਇਰੈਕਟਰੀ, YouTube, jsDelivr, Stripe ਜਾਂ Vercel ਤੱਕ ਪਹੁੰਚ ਸਕਦੀ ਹੈ; ਹਰ ਇੱਕ ਦਾ ਵੇਰਵਾ ਸੈਕਸ਼ਨ 5 ਵਿੱਚ ਹੈ।',
    'privacy.basic.transfers': 'ਤਬਾਦਲੇ',
    'privacy.basic.transfersV':
        'ਉਹ ਪ੍ਰਦਾਤਾ EEA ਤੋਂ ਬਾਹਰ ਹਨ। ਬੇਨਤੀ ਤੁਹਾਡਾ ਬ੍ਰਾਊਜ਼ਰ ਕਰਦਾ ਹੈ ਅਤੇ ਸਿਰਫ਼ ਉਦੋਂ ਜਦੋਂ ਤੁਸੀਂ ਮੰਗਦੇ ਹੋ। ਸੈਕਸ਼ਨ 6 ਸੁਰੱਖਿਆ ਉਪਾਵਾਂ ਦੀ ਵਿਆਖਿਆ ਕਰਦਾ ਹੈ।',
    'privacy.basic.rights': 'ਤੁਹਾਡੇ ਅਧਿਕਾਰ',
    'privacy.basic.rightsV':
        'ਪਹੁੰਚ, ਸੁਧਾਰ, ਮਿਟਾਉਣਾ, ਪਾਬੰਦੀ, ਪੋਰਟੇਬਿਲਟੀ, ਇਤਰਾਜ਼, ਅਤੇ ਸਹਿਮਤੀ ਵਾਪਸ ਲੈਣਾ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਬਹੁਤੇ ਤੁਸੀਂ ਖੁਦ ਪੈਨਲ ਤੋਂ ਵਰਤਦੇ ਹੋ। ਸੈਕਸ਼ਨ 14।',

    'privacy.scope.title': 'ਦੋ ਵੱਖਰੀਆਂ ਚੀਜ਼ਾਂ, ਇੱਕ ਨੀਤੀ',
    'privacy.scope.p1':
        'ਇਹ Chrome ਐਕਸਟੈਂਸ਼ਨ ਅਤੇ ਉਸ ਵੈੱਬਸਾਈਟ ਨੂੰ ਕਵਰ ਕਰਦੀ ਹੈ ਜੋ ਤੁਸੀਂ ਪੜ੍ਹ ਰਹੇ ਹੋ। ਇਹ ਵੱਖਰੇ ਸਾਫਟਵੇਅਰ ਹਨ ਅਤੇ ਇਹਨਾਂ ਦੀਆਂ ਪਰਦੇਦਾਰੀ ਨਾਲ ਜੁੜੀਆਂ ਗੱਲਾਂ ਵੀ ਵੱਖਰੀਆਂ ਹਨ, ਅਤੇ ਦੋਵਾਂ ਨੂੰ ਰਲਾਉਣ ਨਾਲ ਨੀਤੀ ਬੇਅਰਥ ਹੋ ਜਾਂਦੀ ਹੈ। ਜਿੱਥੇ ਵੀ ਕੋਈ ਨਿਯਮ ਇੱਕ ’ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਅਤੇ ਦੂਜੇ ’ਤੇ ਨਹੀਂ, ਉੱਥੇ ਇਹ ਸਪਸ਼ਟ ਦੱਸਿਆ ਗਿਆ ਹੈ।',
    'privacy.scope.p2':
        'ਦੋਵੇਂ Luis Reoyo (GENKI Organización) ਦੁਆਰਾ ਪ੍ਰਕਾਸ਼ਿਤ ਹਨ, ਜੋ ਵੈੱਬਸਾਈਟ ਦੁਆਰਾ ਸੰਭਾਲੇ ਥੋੜ੍ਹੇ ਜਿਹੇ ਡਾਟੇ ਦੇ ਡਾਟਾ ਕੰਟਰੋਲਰ ਵੀ ਹਨ। ਕੋਈ ਡਾਟਾ ਸੁਰੱਖਿਆ ਅਧਿਕਾਰੀ ਨਿਯੁਕਤ ਨਹੀਂ ਕੀਤਾ ਗਿਆ, ਕਿਉਂਕਿ ਇਸ ਪ੍ਰੋਸੈਸਿੰਗ ਦੇ ਪੈਮਾਨੇ ਲਈ GDPR ਦੇ ਆਰਟੀਕਲ 37 ਅਧੀਨ ਇਸਦੀ ਲੋੜ ਨਹੀਂ। ਇਸ ਦਸਤਾਵੇਜ਼ ਦੀ ਹਰ ਗੱਲ ਜਨਤਕ ਸਰੋਤ ਕੋਡ ਨਾਲ ਮਿਲਾ ਕੇ ਜਾਂਚੀ ਜਾ ਸਕਦੀ ਹੈ।',

    'privacy.basis.title': 'ਹਰ ਚੀਜ਼ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਕਿਉਂ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਕਿਸ ਕਾਨੂੰਨੀ ਆਧਾਰ ’ਤੇ',
    'privacy.basis.p1':
        'GDPR ਪੂਰੇ ਉਤਪਾਦ ਲਈ ਇੱਕ ਦੀ ਬਜਾਏ ਹਰ ਮਕਸਦ ਲਈ ਇੱਕ ਕਾਨੂੰਨੀ ਆਧਾਰ ਮੰਗਦਾ ਹੈ, ਇਸ ਲਈ ਉਹ ਹੇਠਾਂ ਦਿੱਤੇ ਗਏ ਹਨ, ਹਰ ਇੱਕ ਇੱਕ ਲਾਈਨ ਵਿੱਚ।',
    'privacy.basis.li1':
        'ਤੁਹਾਡੀ ਡਿਵਾਈਸ ’ਤੇ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਚਲਾਉਣਾ: ਤੁਹਾਡੀ ਸਹਿਮਤੀ, ਜੋ ਐਕਸਟੈਂਸ਼ਨ ਇੰਸਟੌਲ ਕਰਨ ਵੇਲੇ ਅਤੇ ਫਿਰ ਗਤੀਵਿਧੀ ਰਿਕਾਰਡ ਜਾਂ ਸਹਾਇਕ ਵਰਗੀ ਕੋਈ ਵਿਕਲਪਿਕ ਵਿਸ਼ੇਸ਼ਤਾ ਚਾਲੂ ਕਰਨ ਵੇਲੇ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ। ਆਰਟੀਕਲ 6.1.a।',
    'privacy.basis.li2':
        'Google ਨੂੰ ਪ੍ਰੌਮਪਟ ਭੇਜਣਾ, ਰੇਡੀਓ ਡਾਇਰੈਕਟਰੀ ਖੋਜਣਾ ਜਾਂ YouTube ਥੰਬਨੇਲ ਲੋਡ ਕਰਨਾ: ਤੁਹਾਡੀ ਸਹਿਮਤੀ, ਜੋ ਖੁਦ ਉਸ ਕਾਰਵਾਈ ਨਾਲ ਦਿੱਤੀ ਜਾਂਦੀ ਹੈ। ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਨਾ ਮੰਗੋ, ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।',
    'privacy.basis.li3':
        'ਇਹ ਵੈੱਬਸਾਈਟ ਪ੍ਰਦਾਨ ਕਰਨਾ ਅਤੇ ਚਾਲੂ ਰੱਖਣਾ: ਤੁਹਾਡੇ ਮੰਗੇ ਪੰਨੇ ਪਹੁੰਚਾਉਣ ਅਤੇ ਬਿਨਾਂ ਕਿਸੇ ਪਛਾਣਕਰਤਾ ਦੇ ਸਮੁੱਚੇ ਮਾਪ ਵਿੱਚ ਸਾਡਾ ਜਾਇਜ਼ ਹਿੱਤ। ਆਰਟੀਕਲ 6.1.f।',
    'privacy.basis.li4':
        'ਸਾਫਟਵੇਅਰ ਸਹਿਯੋਗ ਯੋਗਦਾਨ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ: ਤੁਹਾਡੇ ਸ਼ੁਰੂ ਕੀਤੇ ਲੈਣ-ਦੇਣ ਨੂੰ ਪੂਰਾ ਕਰਨਾ, ਅਤੇ ਉਸ ਤੋਂ ਬਾਅਦ ਦੀਆਂ ਲੇਖਾ-ਜੋਖਾ ਜ਼ਿੰਮੇਵਾਰੀਆਂ। ਆਰਟੀਕਲ 6.1.b ਅਤੇ 6.1.c।',
    'privacy.basis.p2':
        'ਜਿੱਥੇ ਆਧਾਰ ਸਹਿਮਤੀ ਹੈ, ਤੁਸੀਂ ਇਸਨੂੰ ਕਿਸੇ ਵੀ ਸਮੇਂ ਵਾਪਸ ਲੈ ਸਕਦੇ ਹੋ, ਅਤੇ ਵਾਪਸ ਲੈਣਾ ਸਾਨੂੰ ਬੇਨਤੀ ਕਰਨ ਦੀ ਬਜਾਏ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਇੱਕ ਸਵਿੱਚ ਹੈ। ਵਾਪਸੀ ਪਹਿਲਾਂ ਹੋ ਚੁੱਕੀ ਪ੍ਰੋਸੈਸਿੰਗ ਨੂੰ ਰੱਦ ਨਹੀਂ ਕਰਦੀ, ਜਿਸਦਾ ਇਸ ਮਾਮਲੇ ਵਿੱਚ ਮਤਲਬ ਹੈ ਤੁਹਾਡੀ ਆਪਣੀ ਡਿਵਾਈਸ ’ਤੇ ਪਹਿਲਾਂ ਲਿਖਿਆ ਡਾਟਾ, ਜਿਸਨੂੰ ਤੁਸੀਂ ਖੁਦ ਮਿਟਾ ਸਕਦੇ ਹੋ।',

    'privacy.store.title': 'ਐਕਸਟੈਂਸ਼ਨ ਕੀ ਰੱਖਦੀ ਹੈ, ਅਤੇ ਕਿੱਥੇ',
    'privacy.store.p1':
        'ਐਕਸਟੈਂਸ਼ਨ ਜੋ ਕੁਝ ਜਾਣਦੀ ਹੈ ਉਹ ਤੁਹਾਡੇ ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਪ੍ਰੋਫਾਈਲ ਵਿੱਚ ਰਹਿੰਦਾ ਹੈ, ਉਹਨਾਂ ਦੋ ਥਾਵਾਂ ’ਤੇ ਜੋ Chrome ਇੱਕ ਐਕਸਟੈਂਸ਼ਨ ਨੂੰ ਦਿੰਦਾ ਹੈ: ਇਸਦੇ ਸਟੋਰੇਜ ਖੇਤਰ ਅਤੇ ਇੱਕ IndexedDB ਡਾਟਾਬੇਸ। ਦੋਵਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵੀ ਇੰਟਰਨੈੱਟ ਤੋਂ ਪਹੁੰਚਯੋਗ ਨਹੀਂ, ਅਤੇ ਐਕਸਟੈਂਸ਼ਨ ਦਾ ਕੋਈ ਹਿੱਸਾ ਉਹਨਾਂ ਨੂੰ ਕਿਤੇ ਕਾਪੀ ਨਹੀਂ ਕਰਦਾ।',
