    'privacy.sync.title': 'Chrome ਦਾ ਆਪਣਾ ਸਿੰਕ, ਅਤੇ ਉਸ ਨਾਲ ਕੀ ਜਾਂਦਾ ਹੈ',
    'privacy.sync.p1':
        'ਕੁਝ ਸੈਟਿੰਗਾਂ, ਜਿਵੇਂ ਨਿਯਮ, ਸਨਿੱਪਟ ਅਤੇ ਕੀਬੋਰਡ ਬਦਲਾਅ, ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਸਿੰਕ ਕੀਤੇ ਸਟੋਰੇਜ ਖੇਤਰ ਵਿੱਚ ਲਿਖੀਆਂ ਜਾਂਦੀਆਂ ਹਨ ਤਾਂ ਜੋ ਉਸੇ Chrome ਪ੍ਰੋਫਾਈਲ ਵਿੱਚ ਸਾਈਨ ਇਨ ਦੂਜਾ ਕੰਪਿਊਟਰ ਵੀ ਉਸੇ ਤਰ੍ਹਾਂ ਵਿਵਹਾਰ ਕਰੇ। ਉਹ ਖੇਤਰ Chrome ਦਾ ਹੈ, ਸਾਡਾ ਨਹੀਂ: Chrome ਸਿੰਕ ਚਾਲੂ ਹੋਣ ’ਤੇ Google ਉਸਨੂੰ ਤੁਹਾਡੇ ਖਾਤੇ ਅਧੀਨ ਲੈ ਜਾਂਦਾ ਹੈ; ਬੰਦ ਹੋਣ ’ਤੇ ਇਹ ਇਸੇ ਮਸ਼ੀਨ ’ਤੇ ਰਹਿੰਦਾ ਹੈ ਅਤੇ ਬਿਲਕੁਲ ਲੋਕਲ ਸਟੋਰੇਜ ਵਾਂਗ ਵਿਵਹਾਰ ਕਰਦਾ ਹੈ।',
    'privacy.sync.p2':
        'ਵੈੱਬ ਗਤੀਵਿਧੀ ਰਿਕਾਰਡ ਨੂੰ ਜਾਣ-ਬੁੱਝ ਕੇ ਇਸ ਤੋਂ ਬਾਹਰ ਰੱਖਿਆ ਗਿਆ ਹੈ। ਇਸਨੂੰ ਸਿੰਕ ਕਰਨ ਲਈ ਵੱਖਰਾ ਸਵਿੱਚ ਹੈ, ਜੋ ਤੁਹਾਡੇ ਚਾਲੂ ਕਰਨ ਤੱਕ ਬੰਦ ਰਹਿੰਦਾ ਹੈ, ਕਿਉਂਕਿ ਕੋਈ ਕਿੱਥੇ-ਕਿੱਥੇ ਗਿਆ, ਇਹ ਪੁੱਛੇ ਬਿਨਾਂ ਕਿਤੇ ਭੇਜਣ ਵਾਲੀ ਚੀਜ਼ ਨਹੀਂ। ਤੁਹਾਡੀ API ਕੁੰਜੀ ਕਦੇ ਵੀ ਸਿੰਕ ਨਹੀਂ ਹੁੰਦੀ।',

    'privacy.net.title': 'ਜਦੋਂ ਕੁਝ ਤੁਹਾਡੇ ਬ੍ਰਾਊਜ਼ਰ ਤੋਂ ਬਾਹਰ ਜਾਂਦਾ ਹੈ',
    'privacy.net.p1':
        'ਹੇਠਾਂ ਦਿੱਤੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੈੱਟਵਰਕ ਤੱਕ ਪਹੁੰਚਦੀਆਂ ਹਨ ਕਿਉਂਕਿ ਉਹ ਹੋਰ ਤਰ੍ਹਾਂ ਕੰਮ ਨਹੀਂ ਕਰ ਸਕਦੀਆਂ, ਅਤੇ ਹਰ ਇੱਕ ਦੇ ਨਾਲ ਦੱਸਿਆ ਗਿਆ ਹੈ ਕਿ ਉਹ ਕੀ ਭੇਜਦੀ ਹੈ ਅਤੇ ਕਦੋਂ। ਇਹਨਾਂ ਵਿੱਚੋਂ ਕੋਈ ਵੀ ਸਮਾਂ-ਸਾਰਣੀ ’ਤੇ ਨਹੀਂ ਚੱਲਦੀ ਅਤੇ ਕੋਈ ਵੀ ਬੈਕਗ੍ਰਾਊਂਡ ਵਿੱਚ ਜਾਣਕਾਰੀ ਭੇਜਣ ਦੀ ਉਡੀਕ ਨਹੀਂ ਕਰਦੀ।',
