    'support.ch3.title': 'Chrome Web Store',
    'support.ch3.desc':
        'ਲਿਸਟਿੰਗ ’ਤੇ ਸਹਾਇਤਾ ਟੈਬ, ਉਹਨਾਂ ਲਈ ਜੋ ਸਟੋਰ ਨਹੀਂ ਛੱਡਣਾ ਚਾਹੁੰਦੇ। ਇਹ ਉਸੇ ਇਨਬਾਕਸ ਤੱਕ ਪਹੁੰਚਦੀ ਹੈ, ਥੋੜ੍ਹਾ ਹੌਲੀ।',
