    'support.report.i3': 'ਤੁਸੀਂ ਕੀ ਕੀਤਾ, ਕਦਮ-ਦਰ-ਕਦਮ, ਇੰਨੇ ਵੇਰਵੇ ਨਾਲ ਕਿ ਕੋਈ ਹੋਰ ਵੀ ਕਰ ਸਕੇ।',
